import java.io.FileInputStream
import java.util.Properties

plugins {
    id("com.android.application")
    id("com.google.devtools.ksp")
    id("org.jetbrains.kotlin.android")
    id("org.jetbrains.kotlin.plugin.compose")
}

/**
 * M12: the release key is never in this repository and is never generated by the build agent (it is a
 * local release configuration item). Signing is therefore *optional configuration*, not a required input: if
 * `keystore.properties` (git-ignored) names a keystore that exists, the release build is signed; if it
 * does not, `assembleRelease` still runs and produces an unsigned APK. A build that fails without a key
 * would hide every other release problem; a build that silently ships an unsigned artifact would be
 * worse, so the absence of a key is printed.
 */
val keystoreProperties = Properties().apply {
    val file = rootProject.file("keystore.properties")
    if (file.exists()) FileInputStream(file).use { load(it) }
}
val signingConfigured = keystoreProperties.getProperty("storeFile")
    ?.let { rootProject.file(it).exists() } == true

/**
 * AdMob IDs are configuration, not code: put the real ones in `admobAppId` / `admobInterstitialId`
 * Gradle properties (for example in ~/.gradle/gradle.properties, never in this repository). Until then
 * every build uses Google's published TEST ids, which serve test ads and earn nothing — and a release
 * built that way must not be uploaded, so the build says so (README.md, AdMob).
 */
val admobTestAppId = "ca-app-pub-3940256099942544~3347511713"
val admobTestInterstitialId = "ca-app-pub-3940256099942544/1033173712"
val admobAppId = (findProperty("admobAppId") as String?) ?: admobTestAppId
val admobInterstitialId = (findProperty("admobInterstitialId") as String?) ?: admobTestInterstitialId
if (admobAppId == admobTestAppId) {
    logger.warn(
        "ruler: no admobAppId/admobInterstitialId Gradle properties, so this build uses Google's TEST " +
            "ad ids. Do not upload it to Play — see README.md (AdMob)."
    )
}

if (!signingConfigured) {
    logger.warn(
        "ruler: no usable keystore.properties found, so assembleRelease produces an UNSIGNED " +
            "app-release-unsigned.apk. Signing the release build is a human step — see README.md."
    )
}

android {
    namespace = "com.blueorbit.ruler"
    compileSdk = 36

    defaultConfig {
        applicationId = "com.blueorbit.ruler"
        minSdk = 26
        targetSdk = 36
        versionCode = 1
        versionName = "0.1"
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        manifestPlaceholders["admobAppId"] = admobAppId
        buildConfigField("String", "ADMOB_INTERSTITIAL_ID", "\"$admobInterstitialId\"")
    }

    signingConfigs {
        if (signingConfigured) {
            create("release") {
                storeFile = rootProject.file(keystoreProperties.getProperty("storeFile"))
                storePassword = keystoreProperties.getProperty("storePassword")
                keyAlias = keystoreProperties.getProperty("keyAlias")
                keyPassword = keystoreProperties.getProperty("keyPassword")
            }
        }
    }

    buildTypes {
        release {
            // M12: R8 runs in the shipped build. `proguard-android-optimize.txt` is the AGP default and
            // every library here ships its own consumer rules, so `proguard-rules.pro` adds only what
            // this app needs, each line with a reason.
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
            if (signingConfigured) {
                signingConfig = signingConfigs.getByName("release")
            }
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    // BuildConfig.DEBUG is read in AppContainer to choose the entitlement implementation: a debug-only
    // fake for testing, the real Play implementation in the shipped build.
    buildFeatures {
        buildConfig = true
    }

}

kotlin {
    compilerOptions {
        jvmTarget = org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17
    }
}

// M11R finding 2: the exported Room schema is what makes the v1→v2 migration verifiable. KSP cannot
// parse the @Database annotation, so this single annotation-processing argument is the minimum
// needed; it adds no dependency and nothing to the APK.
ksp {
    arg("room.schemaLocation", "$projectDir/schemas")
}

dependencies {
    implementation(platform("androidx.compose:compose-bom:2026.03.00"))
    implementation("androidx.core:core-ktx:1.17.0")
    implementation("androidx.activity:activity-compose:1.13.0")
    implementation("androidx.lifecycle:lifecycle-viewmodel-compose:2.9.0")
    implementation("androidx.lifecycle:lifecycle-runtime-compose:2.9.0")
    implementation("androidx.navigation:navigation-compose:2.9.7")
    implementation("androidx.compose.ui:ui")
    implementation("androidx.compose.foundation:foundation")
    implementation("androidx.compose.material3:material3")
    // M11V written reason (DESIGN.md §6): Material 3 does not bring the core icon set transitively, and
    // the bar needs four glyphs. This is the same first-party AndroidX Compose group, it adds no
    // permission and no third-party code, and it is the *core* set only — `material-icons-extended`
