    implementation("androidx.compose.material:material-icons-core")
    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-core:1.9.0")
    implementation("androidx.datastore:datastore-preferences:1.1.7")
    implementation("androidx.room:room-runtime:2.8.5")
    implementation("androidx.room:room-ktx:2.8.5")
    ksp("androidx.room:room-compiler:2.8.5")

    // M11 written reason (DECISIONS.md: no new SDK without a written reason): a one-time in-app purchase
    // can only be completed and verified through Google Play, and the app has no other way to know the
    // entitlement. This is the only third-party SDK in the project. It contributes
    // com.android.vending.BILLING to the merged manifest and no ad-services or AD_ID permission —
    // audited in docs/permissions-audit.md. No ads, no analytics, no crash-reporting SDK.
    implementation("com.android.billingclient:billing:9.0.0")

    // Owner decision 2026-10-20 (DECISIONS.md): one interstitial for free users; the Pro unlock removes
    // it. AdMob serves the ad; Google's User Messaging Platform shows the consent form required in the
    // EEA, UK and some US states before any ad is requested. Together they add INTERNET,
    // ACCESS_NETWORK_STATE and AD_ID to the merged manifest (docs/permissions-audit.md).
    implementation("com.google.android.gms:play-services-ads:25.5.0")
    implementation("com.google.android.ump:user-messaging-platform:4.0.0")

    testImplementation("junit:junit:4.13.2")
    // M16 written reason: `viewModelScope` needs a Main dispatcher, and a unit test has to supply one.
    // Without this the calibration wizard's own decisions - which reference it opens with on a given
    // screen, and that Done only fires after the write has happened - could only be checked by hand on a
    // phone. Test-only: it is not in the APK and adds no dependency to the app.
    testImplementation("org.jetbrains.kotlinx:kotlinx-coroutines-test:1.9.0")

    // Used by the one instrumented test that exists (`core/log/MeasurementDaoTest.kt`).
    androidTestImplementation("androidx.test.ext:junit:1.2.1")
    // M18: stated rather than inherited. `defaultConfig` names `androidx.test.runner.AndroidJUnitRunner`
    // as the instrumentation runner, and that class has to be inside the test APK. It used to arrive
    // transitively from the Compose UI-test dependencies removed below; without it the instrumentation dies
    // before enumerating a single test — "Unable to instantiate instrumentation
    // … ClassNotFoundException: androidx.test.runner.AndroidJUnitRunner" — and
    // `connectedDebugAndroidTest` reports 0 tests on the device.
    androidTestImplementation("androidx.test:runner:1.7.0")
    // Removed at M18: `androidx.compose.ui:ui-test-junit4`, its compose-bom platform, and the
    // espresso-core 3.7.0 pin. Nothing in `androidTest` uses them — no Compose UI test runs on this
    // toolchain (BLOCKERS.md). If one is ever attempted, re-add all three **with the pin**: without
    // `androidTestImplementation("androidx.test.espresso:espresso-core:3.7.0")` Compose ui-test pulls
    // espresso-core 3.5.0, which reflects on `InputManager.getInstance()` and aborts every test on
    // Android 17. That half of the blocker is already solved and must not be rediscovered.
}
